<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['delivery15_csrf']))$_SESSION['delivery15_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['delivery15_csrf'];$error=null;$success=null;$sales=[];$deliveries=[];$orderId=(int)($_GET['order']??$_POST['order_id']??0);
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'dispatch');if($action==='dispatch'){$id=sales_step15_dispatch_remaining($pdo,(int)$_POST['order_id'],(string)$_POST['dispatch_date'],(string)$_POST['delivery_mode'],trim((string)($_POST['carrier_name']??'')),trim((string)($_POST['tracking_number']??'')),trim((string)($_POST['notes']??'')));$success='Dispatch #'.$id.' created.';}elseif($action==='status'){$deliveryId=(int)$_POST['delivery_id'];sales_step15_set_delivery_status($pdo,$deliveryId,(string)$_POST['status'],trim((string)($_POST['delivered_date']??''))?:null,trim((string)($_POST['notes']??'')));$success='Delivery #'.$deliveryId.' status updated.';}}$sales=sales_step15_sales_rows($pdo,$orgId);$sql="SELECT d.*,COALESCE(c.customer_name,cl.customer_name_snapshot,q.customer_name,'Unlinked customer') customer_name,COUNT(di.id) item_count,COALESCE(SUM(di.quantity_dispatched),0) total_qty FROM sales_deliveries d LEFT JOIN sales_customer_links cl ON cl.organization_id=d.organization_id AND cl.order_id=d.order_id LEFT JOIN crm_customers c ON c.id=cl.customer_id AND c.organization_id=d.organization_id LEFT JOIN product_quote_order_links ql ON ql.organization_id=d.organization_id AND ql.order_id=d.order_id LEFT JOIN product_quotes q ON q.id=ql.quote_id AND q.organization_id=d.organization_id LEFT JOIN sales_delivery_items di ON di.organization_id=d.organization_id AND di.delivery_id=d.id WHERE d.organization_id=?";$args=[$orgId];if($orderId>0){$sql.=" AND d.order_id=?";$args[]=$orderId;}$sql.=" GROUP BY d.id ORDER BY d.dispatch_date DESC,d.id DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$deliveries=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function sd_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sd_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Delivery Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Delivery & Dispatch</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_invoice.php">Invoices</a><a class="os-btn" href="sales_returns.php">Returns</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a class="active" href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15D • DELIVERY / DISPATCH</div><h1>Track dispatch and delivery without touching stock twice.</h1><p>Dispatch records fulfillment only. Product inventory was already deducted by STEP 13 at sale finalization.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'DELIVERY CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($deliveries) ?> dispatch records</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Delivery diagnostic:</strong> <?= sd_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= sd_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Dispatch Remaining Sale Items</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= sd_h($csrf) ?>"><input type="hidden" name="action" value="dispatch"><label>Product Sale<select name="order_id" required><option value="">Choose active sale…</option><?php foreach($sales as $s):if($s['sale_status']!=='active')continue;?><option value="<?= (int)$s['order_id'] ?>" <?= $orderId===(int)$s['order_id']?'selected':'' ?>>Order #<?= (int)$s['order_id'] ?> • <?= sd_h($s['customer_name'].' • '.strtoupper($s['delivery_status'])) ?></option><?php endforeach;?></select></label><label>Dispatch Date<input type="date" name="dispatch_date" value="<?= sd_h(date('Y-m-d')) ?>" required></label><label>Delivery Mode<select name="delivery_mode"><option value="club_pickup">Club Pickup</option><option value="local_delivery">Local Delivery</option><option value="courier">Courier</option><option value="other">Other</option></select></label><label>Carrier / Courier<input name="carrier_name"></label><label>Tracking Number<input name="tracking_number"></label><label>Notes<textarea name="notes" rows="3"></textarea></label><button>Dispatch All Remaining Qty →</button></form><div class="pp-alert" style="margin-top:12px"><strong>Stock rule:</strong> this action does not change inventory quantity.</div></article><article class="os-card pp-span-7"><h2>Delivery Register</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Dispatch</th><th>Order / Customer</th><th>Date</th><th>Mode</th><th>Tracking</th><th>Qty</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($deliveries as $d):?><tr><td><b><?= sd_h($d['dispatch_number']) ?></b><small>#<?= (int)$d['id'] ?></small></td><td>Order #<?= (int)$d['order_id'] ?><small><?= sd_h($d['customer_name']) ?></small></td><td><?= sd_h($d['dispatch_date']) ?><?= $d['delivered_date']?'<small>Delivered '.sd_h($d['delivered_date']).'</small>':'' ?></td><td><?= sd_h(ucwords(str_replace('_',' ',$d['delivery_mode']))) ?><small><?= sd_h($d['carrier_name']?:'') ?></small></td><td><?= sd_h($d['tracking_number']?:'—') ?></td><td><?= sd_h(sd_n($d['total_qty'])) ?><small><?= (int)$d['item_count'] ?> lines</small></td><td><b><?= sd_h(strtoupper($d['status'])) ?></b></td><td><details><summary>Change</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= sd_h($csrf) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="delivery_id" value="<?= (int)$d['id'] ?>"><select name="status"><option value="dispatched">Dispatched</option><option value="delivered">Delivered</option><option value="failed">Failed</option><option value="cancelled">Cancelled</option></select><input type="date" name="delivered_date" value="<?= sd_h($d['delivered_date']?:date('Y-m-d')) ?>"><input name="notes" placeholder="Optional status note"><button>Update</button></form></details></td></tr><?php endforeach;?><?php if(!$deliveries):?><tr><td colspan="8">No delivery records yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Fulfillment rule:</strong> failed/cancelled dispatch can be re-dispatched; only delivered/dispatched quantities count toward fulfillment.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
